use std::env;
use std::fs;
use std::process;

mod parser;
mod evaluator;
mod exporter;
mod builder;
mod generator;
mod utils;

use parser::Parser;

const VERSION: &str = "1.23.0";

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Argcfile not found, try `argc --argc-help` for help.");
        process::exit(1);
    }

    match args[1].as_str() {
        "--argc-help" => show_help(),
        "--argc-version" => println!("argc {}", VERSION),
        "--argc-eval" => handle_argc_eval(&args),
        "--argc-export" => handle_argc_export(&args),
        "--argc-build" => handle_argc_build(&args),
        "--argc-mangen" => handle_argc_mangen(&args),
        "--argc-completions" => handle_argc_completions(&args),
        "--argc-compgen" => handle_argc_compgen(&args),
        "--argc-create" => handle_argc_create(&args),
        "--argc-run" => handle_argc_run(&args),
        "--argc-parallel" => handle_argc_parallel(&args),
        "--argc-script-path" => handle_argc_script_path(&args),
        "--argc-shell-path" => handle_argc_shell_path(),
        _ => {
            eprintln!("Argcfile not found, try `argc --argc-help` for help.");
            process::exit(1);
        }
    }
}

fn show_help() {
    println!(
        r#"A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval "$(argc --argc-eval "$0" "$@")"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information
"#
    );
}

fn handle_argc_eval(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-eval <FILE> <ARGS~>");
        process::exit(1);
    }

    let file_path = &args[2];
    let script_args = if args.len() > 3 {
        args[3..].to_vec()
    } else {
        vec![]
    };

    match fs::read_to_string(file_path) {
        Ok(content) => {
            let parser = Parser::new(&content);
            let commands = parser.parse();

            match evaluator::generate_eval_code(&content, &commands, &script_args, file_path) {
                Ok(code) => println!("{}", code),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_argc_export(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-export <FILE>");
        process::exit(1);
    }

    let file_path = &args[2];

    match fs::read_to_string(file_path) {
        Ok(content) => {
            let parser = Parser::new(&content);
            let commands = parser.parse();

            match exporter::export_json(&commands) {
                Ok(json) => println!("{}", json),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_argc_build(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-build <FILE> <OUTPATH?>");
        process::exit(1);
    }

    let file_path = &args[2];
    let out_path = if args.len() > 3 {
        args[3].clone()
    } else {
        format!("{}-standalone", file_path)
    };

    match fs::read_to_string(file_path) {
        Ok(content) => {
            let parser = Parser::new(&content);
            let commands = parser.parse();

            match builder::build_standalone(&content, &commands, &out_path) {
                Ok(_) => {},
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_argc_mangen(args: &[String]) {
    if args.len() < 4 {
        eprintln!("Usage: argc --argc-mangen <FILE> <OUTDIR>");
        process::exit(1);
