    let out_dir = &args[3];

    match fs::read_to_string(file_path) {
        Ok(content) => {
            let parser = Parser::new(&content);
            let commands = parser.parse();

            match generator::generate_manpages(&commands, out_dir) {
                Ok(_) => {},
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_argc_completions(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-completions <SHELL> <CMDS>");
        process::exit(1);
    }

    // Placeholder for completion generation
    println!("# Completion generation not yet implemented");
}

fn handle_argc_compgen(args: &[String]) {
    if args.len() < 4 {
        eprintln!("Usage: argc --argc-compgen <SHELL> <FILE> <ARGS>");
        process::exit(1);
    }

    // Placeholder for completion generation
}

fn handle_argc_create(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-create <RECIPES~>");
        process::exit(1);
    }

    let recipes = &args[2..];
    match generator::create_argcfile(recipes) {
        Ok(_) => println!("Argcfile.sh has been successfully created."),
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    }
}

fn handle_argc_run(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-run <FILE> <ARGS~>");
        process::exit(1);
    }

    // Placeholder
    eprintln!("argc-run not yet implemented");
    process::exit(1);
}

fn handle_argc_parallel(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-parallel <FILE> <ARGS~>");
        process::exit(1);
    }

    // Placeholder
    eprintln!("argc-parallel not yet implemented");
    process::exit(1);
}

fn handle_argc_script_path(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-script-path");
        process::exit(1);
    }

    println!("{}", args[2]);
}

fn handle_argc_shell_path() {
