        "--argc-export" => handle_argc_export(&args),
        "--argc-build" => handle_argc_build(&args),
        "--argc-mangen" => handle_argc_mangen(&args),
        "--argc-completions" => handle_argc_completions(&args),
        "--argc-compgen" => handle_argc_compgen(&args),
        "--argc-create" => handle_argc_create(&args),
        "--argc-run" => handle_argc_run(&args),
        "--argc-parallel" => handle_argc_parallel(&args),
        "--argc-script-path" => handle_argc_script_path(&args),
        "--argc-shell-path" => handle_argc_shell_path(),
        _ => {
            eprintln!("Argcfile not found, try `argc --argc-help` for help.");
