    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information
"#
    );
}

fn handle_argc_eval(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: argc --argc-eval <FILE> <ARGS~>");
        process::exit(1);
    }

    let file_path = &args[2];
    let script_args = if args.len() > 3 {
        args[3..].to_vec()
    } else {
        vec![]
    };

    match fs::read_to_string(file_path) {
        Ok(content) => {
            let parser = Parser::new(&content);
            let commands = parser.parse();

            match evaluator::generate_eval_code(&content, &commands, &script_args, file_path) {
                Ok(code) => println!("{}", code),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            process::exit(1);
        }
    }
}

