                short_name = Some(part.to_string());
            } else {
                break;
            }
            i += 1;
        }

        let describe = parts[i..].join(" ");

        cmd.flags.push(FlagDef {
            id: id.clone().to_lowercase(),
            long_name,
            short_name,
            describe,
            multiple_occurs: false,
            env_name: None,
        });
    }

    fn parse_arg(&self, cmd: &mut Command, line: &str) {
        let content = line.strip_prefix("@arg").unwrap().trim();
        let parts: Vec<&str> = content.split_whitespace().collect();

        if parts.is_empty() {
            return;
        }

        let arg_name = parts[0];
        let describe = parts[1..].join(" ");

        let mut id = arg_name.to_string();
        let mut required = false;
        let mut multiple = false;

        if arg_name.ends_with('!') {
            id = arg_name[..arg_name.len() - 1].to_string();
            required = true;
        } else if arg_name.ends_with('+') {
            id = arg_name[..arg_name.len() - 1].to_string();
            multiple = true;
            required = true;
        } else if arg_name.ends_with('*') {
            id = arg_name[..arg_name.len() - 1].to_string();
            multiple = true;
        }

        let notation = id.to_uppercase();

