use crate::parser::{Command, Parser};

pub fn generate_eval_code(
    content: &str,
    _commands: &[Command],
    args: &[String],
    file_path: &str,
) -> Result<String, String> {
    let parser = Parser::new(content);
    let commands = parser.parse();

    if commands.is_empty() {
        return Ok(String::new());
    }

    let mut root_cmd = commands[0].clone();
    root_cmd.name = extract_script_name(file_path);

    // Check for help/version flags  
    let mut help_requested = false;
    let mut version_requested = false;

    for arg in args {
        if arg == "-h" || arg == "--help" {
            help_requested = true;
        } else if arg == "-V" || arg == "--version" {
            version_requested = true;
        }
    }

    if help_requested {
        return generate_help_output(&root_cmd, &root_cmd.name);
    }

    if version_requested {
        return generate_version_output(&root_cmd.version);
    }

    // Try to find a matching subcommand
    if !root_cmd.subcommands.is_empty() && !args.is_empty() {
        if let Some(_) = find_subcommand(&root_cmd.subcommands, &args[0]) {
            return generate_subcommand_eval(content, &root_cmd, args);
        }

        // Check if this is a valid subcommand
        if args[0].chars().next().map(|c| c != '-').unwrap_or(false) {
            // It's not a flag and doesn't match a subcommand
            let mut valid_cmds = vec![];
            for cmd in &root_cmd.subcommands {
                valid_cmds.push(cmd.name.clone());
                valid_cmds.extend(cmd.aliases.clone());
            }
            let cmds_str = valid_cmds.join(", ");
            return Ok(format!(
                r#"command cat >&2 <<-'EOF' 
error: `{}` requires a subcommand but '{}' is not one of them
  [subcommands: {}]
EOF
exit 1"#,
                root_cmd.name, args[0], cmds_str
            ));
        }
    }

    // If we reach here, generate the variable exports
    generate_eval_output(content, args, &root_cmd)
}

fn extract_script_name(path: &str) -> String {
    if let Some(pos) = path.rfind('/') {
        let name = &path[pos + 1..];
        if let Some(dot_pos) = name.find('.') {
            name[..dot_pos].to_string()
        } else {
            name.to_string()
        }
    } else {
        if let Some(dot_pos) = path.find('.') {
            path[..dot_pos].to_string()
        } else {
            path.to_string()
        }
    }
}

fn generate_help_output(root_cmd: &Command, script_name: &str) -> Result<String, String> {
    let mut output = String::new();

    output.push_str(&format!("command cat >&2 <<-'EOF' \n"));
    output.push_str(&format!("{}\n\n", root_cmd.describe));

    let mut usage = format!("USAGE: {} ", script_name);
    if !root_cmd.subcommands.is_empty() {
        usage.push_str("<COMMAND>");
    }
    output.push_str(&format!("{}\n", usage));

    if !root_cmd.subcommands.is_empty() {
        output.push_str("\nCOMMANDS:\n");
        for subcmd in &root_cmd.subcommands {
            let mut aliases_str = String::new();
            if !subcmd.aliases.is_empty() {
                aliases_str = format!(" [aliases: {}]", subcmd.aliases.join(", "));
            }
            output.push_str(&format!("  {:<13}{}{}\n", subcmd.name, subcmd.describe, aliases_str));
        }
    }

    output.push_str("\nEOF\n");
    output.push_str("exit 0");
    Ok(output)
}

fn generate_version_output(version: &std::option::Option<String>) -> Result<String, String> {
    let ver = version.as_ref().map(|v| v.as_str()).unwrap_or("0.0.0");
    Ok(format!("command cat >&2 <<-'EOF'\n{}\nEOF\nexit 0", ver))
}

fn find_subcommand<'a>(subcommands: &'a [Command], name: &str) -> std::option::Option<&'a Command> {
    for cmd in subcommands {
        if cmd.name == name || cmd.aliases.contains(&name.to_string()) {
            return Some(cmd);
        }
    }
    None
}

fn generate_eval_output(
    _content: &str,
    args: &[String],
    root_cmd: &Command,
) -> Result<String, String> {
    let mut vars_str = String::new();
    let mut argc_vars = String::new();

    // Determine which subcommand we're calling
    let mut cmd_index = 0;
    let target_cmd = if !root_cmd.subcommands.is_empty() && !args.is_empty() && !args[0].starts_with('-') {
        if let Some(cmd) = find_subcommand(&root_cmd.subcommands, &args[0]) {
            cmd_index = 1;
            cmd
        } else {
            &root_cmd
        }
    } else {
        &root_cmd
    };

    // Process arguments
    let mut positional_args = vec![];
    let mut i = if cmd_index > 0 { 1 } else { 0 };

    while i < args.len() {
        let arg = &args[i];
        if !arg.starts_with('-') {
            positional_args.push(arg.clone());
        }
        i += 1;
    }

    // Build argc variables
    for (idx, arg) in positional_args.iter().enumerate() {
        if idx < target_cmd.args.len() {
            let arg_def = &target_cmd.args[idx];
            argc_vars.push_str(&format!("argc_{}={};", arg_def.id, arg));
            vars_str.push_str(&format!("argc_{}={}\n", arg_def.id, arg));
        }
    }

    // Add standard variables
    let mut args_array = format!("( {} ", root_cmd.name);
    if cmd_index > 0 {
        args_array.push_str(&args[0]);
        args_array.push(' ');
    }
    for arg in &positional_args {
        args_array.push_str(arg);
        args_array.push(' ');
    }
    args_array.push(')');

    argc_vars.push_str(&format!("argc__args={};", args_array));
    vars_str.push_str(&format!("argc__args={}\n", args_array));

    let fn_name: &str = target_cmd.command_fn.as_ref().map(|s| s.as_str()).unwrap_or(&target_cmd.name);
    argc_vars.push_str(&format!("argc__fn={};", fn_name));
    vars_str.push_str(&format!("argc__fn={}\n", fn_name));

    let mut positionals = String::from("( ");
    for arg in &positional_args {
        positionals.push_str(arg);
        positionals.push(' ');
    }
    positionals.push(')');

    argc_vars.push_str(&format!("argc__positionals={};", positionals));
    vars_str.push_str(&format!("argc__positionals={}\n", positionals));

    // Base64 encode the ARGC_VARS
    let encoded = base64_encode(&argc_vars);

    let mut output = format!("export ARGC_VARS={}\n", encoded);
    output.push_str(&vars_str);

    // Call the function
    output.push_str(fn_name);
    for arg in &positional_args {
        output.push(' ');
        output.push_str(arg);
    }

    Ok(output)
}

fn generate_subcommand_eval(
    _content: &str,
    root_cmd: &Command,
    args: &[String],
) -> Result<String, String> {
    if args.is_empty() {
        return Ok(String::new());
    }

    let subcmd = match find_subcommand(&root_cmd.subcommands, &args[0]) {
        Some(cmd) => cmd,
        None => return Ok(String::new()),
    };

    // Check for help on subcommand
    for arg in args.iter().skip(1) {
        if arg == "-h" || arg == "--help" {
            let mut output = String::new();
            output.push_str(&format!("command cat >&2 <<-'EOF' \n"));
            output.push_str(&format!("{}\n\n", subcmd.describe));

            let mut usage = format!("USAGE: {} {}", root_cmd.name, subcmd.name);
            if !subcmd.args.is_empty() {
                for arg in &subcmd.args {
                    if arg.required {
                        usage.push(' ');
                        usage.push('<');
                        usage.push_str(&arg.notation);
                        usage.push('>');
                    } else if arg.multiple {
                        usage.push(' ');
                        usage.push('[');
                        usage.push_str(&arg.notation);
                        usage.push_str("]...");
                        usage.push(']');
                    } else {
                        usage.push(' ');
                        usage.push('[');
                        usage.push_str(&arg.notation);
                        usage.push(']');
                    }
                }
            }
            output.push_str(&format!("{}\n", usage));

            if !subcmd.args.is_empty() {
                output.push_str("\nARGS:\n");
                for arg in &subcmd.args {
                    let opt_marker = if arg.required { "<" } else { "[" };
                    let close_marker = if arg.required { ">" } else { "]" };
                    if arg.multiple {
                        output.push_str(&format!("  {}{}{}...  {}\n", opt_marker, arg.notation, close_marker, arg.describe));
                    } else {
                        output.push_str(&format!("  {}{}{}  {}\n", opt_marker, arg.notation, close_marker, arg.describe));
                    }
                }
            }

            if !subcmd.flags.is_empty() || !subcmd.options.is_empty() {
                output.push_str("\nOPTIONS:\n");
                for flag in &subcmd.flags {
                    if let Some(short) = &flag.short_name {
                        if let Some(long) = &flag.long_name {
                            output.push_str(&format!("  {}, {}        {}\n", short, long, flag.describe));
                        } else {
                            output.push_str(&format!("  {}              {}\n", short, flag.describe));
                        }
                    } else if let Some(long) = &flag.long_name {
                        output.push_str(&format!("      {}        {}\n", long, flag.describe));
                    }
                }
                for opt in &subcmd.options {
                    if let Some(short) = &opt.short_name {
                        if let Some(long) = &opt.long_name {
                            let notation = opt.notations.first().map(|s| s.as_str()).unwrap_or("VALUE");
                            if opt.multiple_occurs {
                                output.push_str(&format!("  {}, {} [{}]...  {}\n", short, long, notation, opt.describe));
                            } else {
                                output.push_str(&format!("  {}, {} <{}>    {}\n", short, long, notation, opt.describe));
                            }
                        }
                    } else if let Some(long) = &opt.long_name {
                        let notation = opt.notations.first().map(|s| s.as_str()).unwrap_or("VALUE");
                        if opt.multiple_occurs {
                            output.push_str(&format!("      {} [{}]...  {}\n", long, notation, opt.describe));
                        } else {
                            output.push_str(&format!("      {} <{}>    {}\n", long, notation, opt.describe));
                        }
                    }
                }
            }

            output.push_str("  -h,  -help               Print help\n");
            output.push_str("\nEOF\n");
            output.push_str("exit 0");
            return Ok(output);
        }
    }

    // Generate eval for subcommand
    let mut argc_vars = String::new();
    let mut vars_str = String::new();

    // Process positional arguments (skip the command name and subcommand name)
    let mut positional_args = vec![];
    for i in 1..args.len() {
        let arg = &args[i];
        if !arg.starts_with('-') {
            positional_args.push(arg.clone());
        }
    }

    // Build argc variables
    for (idx, arg) in positional_args.iter().enumerate() {
        if idx < subcmd.args.len() {
            let arg_def = &subcmd.args[idx];
            argc_vars.push_str(&format!("argc_{}={};", arg_def.id, arg));
            vars_str.push_str(&format!("argc_{}={}\n", arg_def.id, arg));
        }
    }

    let mut args_array = format!("( {} {} ", root_cmd.name, subcmd.name);
    for arg in &positional_args {
        args_array.push_str(arg);
        args_array.push(' ');
    }
    args_array.push(')');

    argc_vars.push_str(&format!("argc__args={};", args_array));
    vars_str.push_str(&format!("argc__args={}\n", args_array));

