use crate::parser::{Command, Parser};

pub fn generate_eval_code(
    content: &str,
    _commands: &[Command],
    args: &[String],
    file_path: &str,
) -> Result<String, String> {
    let parser = Parser::new(content);
    let commands = parser.parse();

    if commands.is_empty() {
        return Ok(String::new());
    }

    let mut root_cmd = commands[0].clone();
    root_cmd.name = extract_script_name(file_path);

    // Check for help/version flags  
    let mut help_requested = false;
    let mut version_requested = false;

    for arg in args {
        if arg == "-h" || arg == "--help" {
            help_requested = true;
        } else if arg == "-V" || arg == "--version" {
            version_requested = true;
        }
    }

    if help_requested {
        return generate_help_output(&root_cmd, &root_cmd.name);
    }

    if version_requested {
        return generate_version_output(&root_cmd.version);
    }

    // Try to find a matching subcommand
    if !root_cmd.subcommands.is_empty() && !args.is_empty() {
        if let Some(_) = find_subcommand(&root_cmd.subcommands, &args[0]) {
            return generate_subcommand_eval(content, &root_cmd, args);
        }

        // Check if this is a valid subcommand
        if args[0].chars().next().map(|c| c != '-').unwrap_or(false) {
            // It's not a flag and doesn't match a subcommand
            let mut valid_cmds = vec![];
            for cmd in &root_cmd.subcommands {
                valid_cmds.push(cmd.name.clone());
                valid_cmds.extend(cmd.aliases.clone());
            }
            let cmds_str = valid_cmds.join(", ");
            return Ok(format!(
                r#"command cat >&2 <<-'EOF' 
error: `{}` requires a subcommand but '{}' is not one of them
  [subcommands: {}]
EOF
exit 1"#,
                root_cmd.name, args[0], cmds_str
            ));
        }
    }

    // If we reach here, generate the variable exports
    generate_eval_output(content, args, &root_cmd)
}

fn extract_script_name(path: &str) -> String {
    if let Some(pos) = path.rfind('/') {
        let name = &path[pos + 1..];
        if let Some(dot_pos) = name.find('.') {
            name[..dot_pos].to_string()
        } else {
            name.to_string()
        }
    } else {
        if let Some(dot_pos) = path.find('.') {
            path[..dot_pos].to_string()
        } else {
            path.to_string()
        }
    }
}

fn generate_help_output(root_cmd: &Command, script_name: &str) -> Result<String, String> {
    let mut output = String::new();

    output.push_str(&format!("command cat >&2 <<-'EOF' \n"));
    output.push_str(&format!("{}\n\n", root_cmd.describe));

    let mut usage = format!("USAGE: {} ", script_name);
    if !root_cmd.subcommands.is_empty() {
        usage.push_str("<COMMAND>");
    }
    output.push_str(&format!("{}\n", usage));

    if !root_cmd.subcommands.is_empty() {
        output.push_str("\nCOMMANDS:\n");
        for subcmd in &root_cmd.subcommands {
            let mut aliases_str = String::new();
            if !subcmd.aliases.is_empty() {
                aliases_str = format!(" [aliases: {}]", subcmd.aliases.join(", "));
            }
            output.push_str(&format!("  {:<13}{}{}\n", subcmd.name, subcmd.describe, aliases_str));
        }
    }

    output.push_str("\nEOF\n");
    output.push_str("exit 0");
    Ok(output)
}

fn generate_version_output(version: &std::option::Option<String>) -> Result<String, String> {
    let ver = version.as_ref().map(|v| v.as_str()).unwrap_or("0.0.0");
    Ok(format!("command cat >&2 <<-'EOF'\n{}\nEOF\nexit 0", ver))
}

fn find_subcommand<'a>(subcommands: &'a [Command], name: &str) -> std::option::Option<&'a Command> {
    for cmd in subcommands {
        if cmd.name == name || cmd.aliases.contains(&name.to_string()) {
            return Some(cmd);
        }
    }
    None
}

fn generate_eval_output(
    _content: &str,
    args: &[String],
    root_cmd: &Command,
) -> Result<String, String> {
    let mut vars_str = String::new();
    let mut argc_vars = String::new();

    // Determine which subcommand we're calling
    let mut cmd_index = 0;
    let target_cmd = if !root_cmd.subcommands.is_empty() && !args.is_empty() && !args[0].starts_with('-') {
