    for opt in &cmd.options {
        if first {
            first = false;
        } else {
            json.push_str(",\n");
        }
        let num_args = if opt.multiple_values { format!("[0, 999]") } else { format!("[1, 1]") };
        json.push_str(&format!(
r#"        {{
          "id": "{}",
          "long_name": {},
          "short_name": {},
          "describe": "{}",
          "flag": false,
          "notations": {},
          "required": {},
          "multiple_values": {},
          "multiple_occurs": {},
          "num_args": {},
          "delimiter": null,
          "terminated": false,
          "prefixed": false,
          "assigned": false,
          "default": null,
          "choice": null,
          "env": null,
          "inherited": false
        }}"#,
            escape_json(&opt.id),
            opt.long_name.as_ref().map(|s| format!(r#""{}""#, escape_json(s))).unwrap_or_else(|| "null".to_string()),
            opt.short_name.as_ref().map(|s| format!(r#""{}""#, escape_json(s))).unwrap_or_else(|| "null".to_string()),
            escape_json(&opt.describe),
            format_notations(&opt.notations),
            opt.required,
            opt.multiple_values,
            opt.multiple_occurs,
            num_args
        ));
    }

    // Add help flag
    if !first {
        json.push_str(",\n");
    }
    json.push_str(&format!(r#"        {{
          "id": "help",
          "long_name": "--help",
          "short_name": "-h",
          "describe": "Print help",
          "flag": true,
          "notations": [],
          "required": false,
          "multiple_values": false,
          "multiple_occurs": false,
          "num_args": [0, 0],
          "delimiter": null,
          "terminated": false,
          "prefixed": false,
          "assigned": false,
          "default": null,
          "choice": null,
          "env": null,
          "inherited": false
        }}"#));

    json.push_str("\n      ],\n");

    // positionals
    json.push_str("      \"positionals\": [\n");
    for (i, arg) in cmd.args.iter().enumerate() {
        if i > 0 {
            json.push_str(",\n");
        }
        json.push_str(&format!(
r#"        {{
          "id": "{}",
          "describe": "{}",
          "notation": "{}",
          "required": {},
          "multiple": {},
          "delimiter": null,
          "terminated": false,
          "default": null,
          "choice": null,
          "env": null
        }}"#,
            escape_json(&arg.id),
            escape_json(&arg.describe),
            escape_json(&arg.notation),
            arg.required,
            arg.multiple
        ));
    }
    json.push_str("\n      ],\n");

    json.push_str("      \"envs\": [],\n");
    json.push_str("      \"subcommands\": [],\n");
    json.push_str(&format!("      \"command_fn\": {}\n", 
        cmd.command_fn.as_ref().map(|s| format!(r#""{}""#, s)).unwrap_or_else(|| "null".to_string())));
    json.push_str("    }");

    json
}

fn format_notations(notations: &[String]) -> String {
    if notations.is_empty() {
        return "[]".to_string();
    }
    let mut result = String::from("[");
    for (i, n) in notations.iter().enumerate() {
        if i > 0 {
            result.push_str(", ");
        }
        result.push('"');
        result.push_str(&escape_json(n));
        result.push('"');
    }
    result.push(']');
    result
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}
