use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct Command {
    pub name: String,
    pub describe: String,
    pub aliases: Vec<String>,
    pub options: Vec<OptionDef>,
    pub flags: Vec<FlagDef>,
    pub args: Vec<ArgDef>,
    pub envs: Vec<EnvDef>,
    pub meta: HashMap<String, String>,
