    pub prefixed: bool,
    pub assigned: bool,
    pub env_name: std::option::Option<String>,
}

#[derive(Debug, Clone)]
pub struct FlagDef {
    pub id: String,
    pub long_name: std::option::Option<String>,
    pub short_name: std::option::Option<String>,
    pub describe: String,
    pub multiple_occurs: bool,
    pub env_name: std::option::Option<String>,
}

#[derive(Debug, Clone)]
pub struct ArgDef {
    pub id: String,
    pub notation: String,
    pub describe: String,
    pub required: bool,
    pub multiple: bool,
    pub default: std::option::Option<String>,
    pub choice: std::option::Option<Vec<String>>,
    pub choice_fn: std::option::Option<String>,
    pub delimiter: std::option::Option<char>,
    pub terminated: bool,
    pub env_name: std::option::Option<String>,
}

#[derive(Debug, Clone)]
pub struct EnvDef {
    pub name: String,
    pub describe: String,
    pub required: bool,
    pub default: std::option::Option<String>,
    pub choice: std::option::Option<Vec<String>>,
    pub choice_fn: std::option::Option<String>,
}

pub struct Parser {
    pub content: String,
}

impl Parser {
    pub fn new(content: &str) -> Self {
        Parser {
            content: content.to_string(),
        }
    }

    pub fn parse(&self) -> Vec<Command> {
        let lines: Vec<&str> = self.content.lines().collect();
        let mut i = 0;
        let mut root_cmd: std::option::Option<Command> = None;
        let mut current_meta: HashMap<String, String> = HashMap::new();
        let mut current_describe = String::new();

        while i < lines.len() {
            let line = lines[i];

            if line.trim().starts_with('#') {
                if let Some(rest) = line.trim().strip_prefix('#') {
                    let trimmed = rest.trim();

                    if trimmed.starts_with("@describe") {
                        current_describe = trimmed.strip_prefix("@describe").unwrap().trim().to_string();
                    } else if trimmed.starts_with("@meta") {
                        let content = trimmed.strip_prefix("@meta").unwrap().trim();
                        let parts: Vec<&str> = content.splitn(2, ' ').collect();
                        if !parts.is_empty() {
                            current_meta.insert(parts[0].to_string(), if parts.len() > 1 { parts[1].to_string() } else { String::new() });
                        }
                    } else if trimmed.starts_with("@cmd") {
                        // Found a subcommand
                        if root_cmd.is_none() {
                            root_cmd = Some(Command {
                                name: String::new(),
                                describe: current_describe.clone(),
                                long_describe: String::new(),
                                aliases: vec![],
                                options: vec![],
                                flags: vec![],
                                args: vec![],
                                envs: vec![],
                                meta: current_meta.clone(),
                                subcommands: vec![],
                                command_fn: None,
                                version: None,
                            });
                        }

                        // Extract description from @cmd line
                        let cmd_desc = trimmed.strip_prefix("@cmd").unwrap().trim().to_string();
                        i += 1;
                        let mut subcmd = self.parse_subcommand(&lines, &mut i);
                        if !cmd_desc.is_empty() {
                            subcmd.describe = cmd_desc;
                        }
                        if let Some(ref mut root) = root_cmd {
                            root.subcommands.push(subcmd);
                        }
                        continue;
                    }
                }
            }

            i += 1;
        }

        let mut commands = vec![];
        if let Some(mut cmd) = root_cmd {
            cmd.name = "script".to_string();
            commands.push(cmd);
        } else {
            commands.push(Command {
                name: "script".to_string(),
                describe: current_describe,
                aliases: vec![],
                options: vec![],
                flags: vec![],
                args: vec![],
                envs: vec![],
                meta: current_meta,
                subcommands: vec![],
                command_fn: None,
                version: None,
                long_describe: String::new(),
            });
        }

        commands
    }

    fn parse_subcommand(&self, lines: &[&str], i: &mut usize) -> Command {
        let mut cmd = Command {
            name: String::new(),
            describe: String::new(),
            long_describe: String::new(),
            aliases: vec![],
            options: vec![],
            flags: vec![],
            args: vec![],
            envs: vec![],
            meta: HashMap::new(),
            subcommands: vec![],
            command_fn: None,
            version: None,
        };

        // Parse comment block for this subcommand
        while *i < lines.len() {
            let line = lines[*i];

            if line.trim().starts_with('#') {
                if let Some(rest) = line.trim().strip_prefix('#') {
                    let trimmed = rest.trim();

                    if trimmed.starts_with("@alias") {
                        let alias = trimmed.strip_prefix("@alias").unwrap().trim().to_string();
                        cmd.aliases.push(alias);
                    } else if trimmed.starts_with("@describe") {
                        cmd.describe = trimmed.strip_prefix("@describe").unwrap().trim().to_string();
                    } else if trimmed.starts_with("@arg") {
                        self.parse_arg(&mut cmd, trimmed);
                    } else if trimmed.starts_with("@flag") {
                        self.parse_flag(&mut cmd, trimmed);
                    } else if trimmed.starts_with("@option") {
                        self.parse_option(&mut cmd, trimmed);
                    } else if trimmed.starts_with("@env") {
                        self.parse_env(&mut cmd, trimmed);
                    } else if trimmed.starts_with("@cmd") {
                        // Next subcommand starts, back up
                        return cmd;
                    }
                }
                *i += 1;
            } else if (line.trim().ends_with('(') || line.trim().contains("() {")) && !line.trim().starts_with('#') {
                // Function definition line
                let func_name = self.extract_function_name(line);
                cmd.name = func_name.clone();
                cmd.command_fn = Some(func_name);
                *i += 1;
                break;
            } else {
                // Empty line or non-comment, end of subcommand definition
                if !line.trim().is_empty() && !line.trim().starts_with('#') {
                    break;
                }
                *i += 1;
            }
        }

        cmd
    }

    fn extract_function_name(&self, line: &str) -> String {
        let trimmed = line.trim();
        if let Some(paren_idx) = trimmed.find('(') {
            trimmed[..paren_idx].to_string()
        } else {
            String::new()
        }
    }

    fn parse_option(&self, cmd: &mut Command, line: &str) {
        let content = line.strip_prefix("@option").unwrap().trim();
        let parts: Vec<&str> = content.split_whitespace().collect();

        if parts.is_empty() {
            return;
        }

        let mut long_name = None;
        let mut short_name = None;
        let mut id = String::new();
        let mut i = 0;

        // Parse option names
        while i < parts.len() {
            let part = parts[i];
            if part.starts_with("--") {
                long_name = Some(part.to_string());
                id = part[2..].split('[').next().unwrap_or("").to_string();
                id = id.split('=').next().unwrap_or(&id).to_string();
                id = id.split('<').next().unwrap_or(&id).to_string();
            } else if part.starts_with('-') && part.len() == 2 {
                short_name = Some(part.to_string());
            } else {
                break;
            }
            i += 1;
        }

        let describe = parts[i..].join(" ");

        cmd.options.push(OptionDef {
            id: id.clone().to_lowercase(),
            long_name,
            short_name,
            describe,
            notations: vec![],
            required: false,
            multiple_values: false,
            multiple_occurs: false,
            default: None,
            choice: None,
            choice_fn: None,
            delimiter: None,
            terminated: false,
            prefixed: false,
            assigned: false,
            env_name: None,
        });
    }

    fn parse_flag(&self, cmd: &mut Command, line: &str) {
        let content = line.strip_prefix("@flag").unwrap().trim();
        let parts: Vec<&str> = content.split_whitespace().collect();

        if parts.is_empty() {
            return;
        }

        let mut long_name = None;
        let mut short_name = None;
        let mut id = String::new();
        let mut i = 0;

        // Parse flag names
        while i < parts.len() {
            let part = parts[i];
            if part.starts_with("--") {
                long_name = Some(part.to_string());
                id = part[2..].to_string();
            } else if part.starts_with('-') && part.len() == 2 {
                short_name = Some(part.to_string());
            } else {
                break;
            }
            i += 1;
        }

        let describe = parts[i..].join(" ");

        cmd.flags.push(FlagDef {
            id: id.clone().to_lowercase(),
            long_name,
            short_name,
            describe,
            multiple_occurs: false,
            env_name: None,
        });
    }

    fn parse_arg(&self, cmd: &mut Command, line: &str) {
        let content = line.strip_prefix("@arg").unwrap().trim();
        let parts: Vec<&str> = content.split_whitespace().collect();

        if parts.is_empty() {
            return;
        }

        let arg_name = parts[0];
        let describe = parts[1..].join(" ");

        let mut id = arg_name.to_string();
        let mut required = false;
        let mut multiple = false;

        if arg_name.ends_with('!') {
            id = arg_name[..arg_name.len() - 1].to_string();
            required = true;
        } else if arg_name.ends_with('+') {
            id = arg_name[..arg_name.len() - 1].to_string();
            multiple = true;
            required = true;
        } else if arg_name.ends_with('*') {
            id = arg_name[..arg_name.len() - 1].to_string();
            multiple = true;
        }

        let notation = id.to_uppercase();

        cmd.args.push(ArgDef {
            id,
            notation,
            describe,
            required,
            multiple,
            default: None,
            choice: None,
            choice_fn: None,
            delimiter: None,
            terminated: false,
            env_name: None,
        });
    }

    fn parse_env(&self, _cmd: &mut Command, _line: &str) {
        // Placeholder
    }
}
