fn extract_script_name_from_path(path: &str) -> String {
    if let Some(pos) = path.rfind('/') {
        let name = &path[pos + 1..];
        if let Some(dot_pos) = name.find('.') {
            name[..dot_pos].to_string()
        } else {
            name.to_string()
        }
    } else {
        if let Some(dot_pos) = path.find('.') {
            path[..dot_pos].to_string()
        } else {
            path.to_string()
        }
    }
